<script setup>
import {ref,computed,onBeforeUnmount,onMounted,nextTick} from 'vue'
const props=defineProps({dataset:Object}),emit=defineEmits(['explore'])
const region=ref('all'),year=ref(2025),selected=ref(null),playing=ref(false),chart=ref(null),closeButton=ref(null),dialog=ref(null)
let timer=null,previousFocus=null
const map=computed(()=>props.dataset.landscape)
const organizations=computed(()=>map.value.organizations.filter(o=>region.value==='all'||o.region===region.value))
const years=Array.from({length:9},(_,i)=>2017+i)
const x=y=>280+(y-2017)*108
const positions=computed(()=>{let last='',y=140;return organizations.value.map(o=>{if(last&&last!==o.group)y+=22;last=o.group;const r={...o,y};y+=66;return r})})
const height=computed(()=>(positions.value.at(-1)?.y||150)+55)
const events=computed(()=>map.value.events.filter(e=>organizations.value.some(o=>o.id===e.org)))
const connections=computed(()=>map.value.connections.filter(c=>organizations.value.some(o=>o.id===c.source)&&organizations.value.some(o=>o.id===c.target)))
const color=o=>o.region==='cn'?'#ad1433':'#35647c'
const orgFor=id=>positions.value.find(o=>o.id===id)
const startFor=id=>Math.min(...map.value.events.filter(e=>e.org===id).map(e=>x(e.year)),...map.value.connections.flatMap(c=>c.source===id?[x(c.year)-27]:c.target===id?[x(c.year)+27]:[]))
const endFor=id=>id==='brain'?x(2023)-27:1195
function line(c){const a=orgFor(c.source),b=orgFor(c.target),left=x(c.year)-27,right=x(c.year)+27;return `M${left},${a.y} C${left+42},${a.y} ${right-42},${b.y} ${right},${b.y}`}
function stop(){clearInterval(timer);playing.value=false}
function play(){if(playing.value){stop();return}if(year.value>=2025)year.value=2017;playing.value=true;timer=setInterval(()=>{if(year.value>=2025)stop();else year.value++},1100)}
function open(item,kind='event'){previousFocus=document.activeElement;selected.value={...item,kind};nextTick(()=>closeButton.value?.focus())}
function close(){selected.value=null;previousFocus?.focus?.()}
function key(e){if(e.key==='Escape'&&selected.value)close();if(e.key==='Tab'&&selected.value){const els=dialog.value?.querySelectorAll('button,a');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}
async function full(){try{if(document.fullscreenElement)await document.exitFullscreen();else await chart.value?.requestFullscreen()}catch{}}
onMounted(()=>window.addEventListener('keydown',key));onBeforeUnmount(()=>{stop();window.removeEventListener('keydown',key)})
</script>
<template><div class="research-landscape">
  <div class="landscape-intro"><div class="intro-mark">01<span>研究版图</span></div><div><h3>基础方法、模型研发与系统工具，共同推动技术演进</h3><p>从 Transformer、GLM 到推理模型，再到 FlashAttention 与 vLLM：代表成果呈现出不同机构在架构、模型和系统环节的持续积累。</p></div></div>
  <div class="landscape-metrics"><div><span>本项目 AI 基金</span><strong>21,078<small>项</small></strong></div><div><span>基金登记成果关系</span><strong>388,629<small>条</small></strong></div><div><span>已核验负责人接续</span><strong>{{dataset.continuity.length}}<small>条</small></strong></div><button @click="emit('explore')"><span>从版图回到本项目数据</span><b>查看基金研究接续 <i>→</i></b></button></div>
  <section ref="chart" class="landscape-panel">
    <header class="map-head"><div><p class="landscape-eyebrow">机构 × 时间 × 代表成果</p><h3>研究力量版图</h3><p>2017—2025 · 机构代表成果与组织衍生</p></div><button class="outline" @click="full">全屏展示 ↗</button></header>
    <div class="map-controls"><div class="region-buttons" aria-label="机构范围"><button v-for="[id,label] in [['all','全部机构'],['cn','中国机构'],['intl','国际机构']]" :key="id" :class="{active:region===id}" @click="region=id">{{label}}</button></div><div class="time-control"><button @click="play" :aria-label="playing?'暂停年份播放':'播放年份演进'">{{playing?'暂停':'播放'}} <span>{{playing?'Ⅱ':'▶'}}</span></button><input aria-label="版图截至年份" v-model.number="year" type="range" min="2017" max="2025" step="1" @input="stop"><strong>{{year}}</strong></div></div>
    <div class="map-legend"><span><i class="dot cn"></i>中国机构</span><span><i class="dot intl"></i>国际机构</span><span><i class="branch"></i>组织衍生 / 合并</span><small>点击成果或支线，查看研究内容与来源</small></div>
    <div class="map-scroll"><svg class="landscape-svg" :viewBox="`0 0 1220 ${height}`" role="img" aria-label="按机构横向展开的2017至2025年研究力量与代表成果时间图">
      <rect x="226" y="10" width="306" height="30" rx="7" fill="#f0ece8"/><text x="379" y="30" class="phase">架构与预训练</text><rect x="536" y="10" width="320" height="30" rx="7" fill="#f6f4f1"/><text x="696" y="30" class="phase">模型规模与对齐</text><rect x="860" y="10" width="334" height="30" rx="7" fill="#f0ece8"/><text x="1027" y="30" class="phase">模型生态与推理</text>
      <g v-for="y in years" :key="y"><line :x1="x(y)" y1="90" :x2="x(y)" :y2="height-20" stroke="#ebe7e3"/><text :x="x(y)" y="72" text-anchor="middle" :class="['year-label',{current:y===year}]">{{y}}</text></g>
      <rect v-if="year<2025" :x="x(year)+40" y="90" :width="Math.max(0,1195-x(year)-40)" :height="height-110" fill="#efeeec" opacity=".55"/>
      <g v-for="(org,i) in positions" :key="org.id"><rect x="8" :y="org.y-37" width="1193" height="66" rx="8" :fill="i%2===0?'#f7f5f2':'#fff'" opacity=".82"/><line x1="8" :y1="org.y-28" x2="8" :y2="org.y+22" :stroke="color(org)" stroke-width="3"/><text x="26" :y="org.y-9" class="org-name">{{org.name}}</text><text x="26" :y="org.y+12" class="org-sub">{{org.subtitle}}</text><line :x1="startFor(org.id)" :y1="org.y" :x2="endFor(org.id)" :y2="org.y" :stroke="color(org)" stroke-width="2" opacity=".23"/><line v-if="x(year)+40>=startFor(org.id)" :x1="startFor(org.id)" :y1="org.y" :x2="Math.min(x(year)+40,endFor(org.id))" :y2="org.y" :stroke="color(org)" stroke-width="2" opacity=".4"/></g>
      <g v-for="c in connections" :key="c.id" :opacity="c.year<=year?1:.14" class="map-link" role="button" tabindex="0" :aria-label="`${c.year}年${c.label}`" @click="open(c,'connection')" @keydown.enter="open(c,'connection')" @keydown.space.prevent="open(c,'connection')"><path :d="line(c)" stroke="transparent" stroke-width="22" fill="none"/><path :d="line(c)" :stroke="color(orgFor(c.source))" stroke-width="2" stroke-dasharray="4 4" fill="none"/><text :x="x(c.year)-40" :y="(orgFor(c.source).y+orgFor(c.target).y)/2+5" text-anchor="end" class="connection-label" :fill="color(orgFor(c.source))">{{c.label}}</text></g>
      <g v-for="event in events" :key="event.id" :transform="`translate(${x(event.year)},${orgFor(event.org).y})`" :opacity="event.year<=year?1:.13" class="map-node" role="button" tabindex="0" :aria-label="`${orgFor(event.org).name}，${event.year}年，${event.label}`" @click="open(event)" @keydown.enter="open(event)" @keydown.space.prevent="open(event)"><circle r="24" fill="transparent"/><circle r="12" :fill="color(orgFor(event.org))" opacity=".12"/><circle r="6.5" :fill="color(orgFor(event.org))" stroke="white" stroke-width="1.5"/><text y="-20" text-anchor="middle" :fill="color(orgFor(event.org))" class="event-label">{{event.label}}</text></g>
    </svg></div>
    <footer class="map-footer"><span>按成果首次公开年份排列 · 机构主干起点取本图首条记录</span><span>{{organizations.length}} 条机构主干 · {{events.filter(e=>e.year<=year).length}} 个成果节点</span></footer>
    <Teleport to="body" :disabled="!!selected&&!!chart&&!!chart.matches?.(':fullscreen')"><div v-if="selected" class="map-modal-layer" @click.self="close"><section ref="dialog" class="map-dialog" role="dialog" aria-modal="true" aria-labelledby="landscape-detail-title"><button ref="closeButton" class="dialog-close" aria-label="关闭研究成果详情" @click="close">×</button><p class="landscape-eyebrow">{{selected.year}} · {{selected.kind==='connection'?'组织发展':selected.topic}}</p><h3 id="landscape-detail-title">{{selected.label}}</h3><p class="detail-org">{{selected.kind==='connection'?`${orgFor(selected.source)?.name} → ${orgFor(selected.target)?.name}`:orgFor(selected.org)?.name}}</p><p class="detail-description">{{selected.description}}</p><a :href="selected.url" target="_blank" rel="noopener noreferrer">查看论文或机构原文 ↗</a></section></div></Teleport>
  </section>
  <div class="landscape-readings"><article><span>高校与企业</span><h4>研究积累可以沿组织衍生继续发展</h4><p>清华知识工程实验室转化智谱，随后持续开展 GLM 系列联合研究。组织改变后，已有研究方向仍可继续深化。</p><button @click="open(map.connections[0],'connection')">查看组织衍生依据 →</button></article><article><span>基础方法与系统</span><h4>支撑作用也体现在共同使用的工具中</h4><p>FlashAttention 与 vLLM 将注意力计算和显存管理转化为可复用系统能力，让方法研究进入模型训练与服务环节。</p><button @click="open(map.events.find(e=>e.label==='vLLM'))">查看代表成果 →</button></article><article><span>基金与研究力量</span><h4>沿项目与论文观察长期积累</h4><p>回到本项目基金数据，进一步查看机构的持续参与、负责人的前后项目，以及小样本学习等具体研究问题如何延续。</p><button @click="emit('explore')">进入基金研究接续 →</button></article></div>
</div></template>
<style scoped>
.research-landscape{color:#302c29}.landscape-intro{display:flex;gap:25px;padding:22px 0 26px;align-items:flex-start}.intro-mark{font-size:38px;font-weight:700;line-height:1;color:#ae0d28;border-right:1px solid #ded6ce;padding:0 25px 0 0;flex:none}.intro-mark span{display:block;font-size:11px;letter-spacing:1px;margin-top:13px;font-weight:500}.landscape-intro h3{margin:0 0 9px;font-size:24px;line-height:1.5}.landscape-intro p{margin:0;color:#78716c;line-height:1.85;font-size:15px;max-width:940px}.landscape-metrics{display:grid;grid-template-columns:1fr 1fr 1fr 1.15fr;margin:2px 0 28px;border:1px solid #e5dfd9;border-radius:12px;background:#fff;padding:24px 0}.landscape-metrics>div,.landscape-metrics>button{padding:0 23px;border-right:1px solid #e9e3dd}.landscape-metrics span{font-size:13px;color:#8c8178;display:block}.landscape-metrics strong{display:block;font-size:32px;color:#ad1433;letter-spacing:-.8px;margin-top:10px;line-height:1.2}.landscape-metrics small{font-size:13px;color:#8a8077;margin-left:7px;font-weight:400}.landscape-metrics button{background:none;border:0;text-align:left;cursor:pointer}.landscape-metrics button b{display:block;font-size:16px;margin-top:16px;color:#64363d}.landscape-metrics i{font-style:normal;margin-left:10px}.landscape-panel{border:1px solid #e5dfd9;border-radius:16px;background:#fff;padding:28px 24px 18px;position:relative}.map-head{display:flex;justify-content:space-between;align-items:center;gap:16px}.landscape-eyebrow{font-size:11px;color:#9a716c;letter-spacing:1.7px;margin:0 0 8px;font-weight:600}.map-head h3{font-size:29px;margin:0;color:#302b28;line-height:1.3}.map-head>div>p:last-child{font-size:14px;color:#8a817a;margin:9px 0 0}.outline{border:1px solid #ded6cf;background:#fff;padding:9px 14px;border-radius:7px;font-size:13px;color:#76655c;cursor:pointer}.map-controls{margin:24px 0 18px;padding:14px 0;border-top:1px solid #efebe6;border-bottom:1px solid #efebe6;display:flex;justify-content:space-between;gap:18px;align-items:center;flex-wrap:wrap}.region-buttons{display:flex;gap:6px}.region-buttons button{border:0;background:#f5f3ef;border-radius:6px;color:#81786f;padding:9px 13px;cursor:pointer;font-size:13px}.region-buttons .active{background:#ad1433;color:#fff}.time-control{display:flex;gap:12px;align-items:center}.time-control button{color:#ad1433;background:none;border:0;font-size:13px;cursor:pointer}.time-control input{width:165px;accent-color:#ad1433;cursor:pointer}.time-control strong{font-size:23px;color:#ad1433;font-variant-numeric:tabular-nums}.time-control span{font-size:10px;margin-left:6px}.map-legend{display:flex;gap:20px;align-items:center;font-size:12px;color:#8c8178;flex-wrap:wrap;margin-bottom:15px}.map-legend>span{display:flex;align-items:center;gap:6px}.dot{width:8px;height:8px;border-radius:50%;display:inline-block}.cn{background:#ad1433}.intl{background:#35647c}.branch{border-top:2px dashed #887f76;width:22px}.map-legend small{margin-left:auto;font-size:12px}.map-scroll{overflow:auto}.landscape-svg{width:100%;min-width:1100px;display:block;font-family:inherit}.phase{text-anchor:middle;fill:#817870;font-size:13px;font-weight:600}.year-label{font-size:14px;fill:#968c83;font-weight:600}.year-label.current{fill:#ad1433;font-weight:800}.org-name{font-size:16px;fill:#3e3833;font-weight:650}.org-sub{font-size:11px;fill:#9a9087}.event-label{font-size:13px;font-weight:650;paint-order:stroke;stroke:white;stroke-width:3;stroke-linejoin:round}.connection-label{font-size:11px;paint-order:stroke;stroke:white;stroke-width:3}.map-node,.map-link{cursor:pointer;transition:opacity .35s}.map-node:hover circle:nth-child(2){opacity:.28}.map-node:focus-visible,.map-link:focus-visible{outline:2px solid #b36a78;outline-offset:2px}.map-footer{padding:16px 0 0;display:flex;justify-content:space-between;gap:20px;color:#94897f;font-size:11px;line-height:1.8;border-top:1px solid #efebe6}.landscape-readings{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin:29px 0 8px}.landscape-readings article{padding:20px 0;border-top:2px solid #b5838a}.landscape-readings span{font-size:12px;color:#9a817b}.landscape-readings h4{font-size:19px;line-height:1.6;margin:10px 0;color:#493a35}.landscape-readings p{font-size:14px;line-height:1.9;color:#847a72;margin:0 0 15px}.landscape-readings button{border:0;background:none;color:#ae0d28;padding:0;font-size:13px;cursor:pointer}.landscape-panel:fullscreen{overflow:auto;padding:32px 5%;border-radius:0}.landscape-panel:fullscreen .landscape-svg{max-width:1600px;margin:auto}.map-modal-layer{position:fixed;inset:0;background:#26232055;backdrop-filter:blur(3px);z-index:200;display:flex;align-items:center;justify-content:center;padding:24px}.map-dialog{background:#fffdfb;border:1px solid #e3d7ce;border-radius:17px;padding:38px;max-width:520px;width:100%;position:relative;box-shadow:0 20px 100px #2018152b;color:#3b322e}.dialog-close{position:absolute;right:16px;top:12px;font-size:27px;border:0;background:none;color:#95877e;cursor:pointer}.map-dialog h3{font-size:30px;margin:14px 0 9px;line-height:1.35}.detail-org{font-size:14px;color:#947f74}.detail-description{font-size:17px;line-height:1.9;margin:22px 0 26px}.map-dialog a{display:inline-block;background:#ae0d28;color:#fff;border-radius:7px;padding:11px 18px;font-size:14px;text-decoration:none}.map-dialog a:focus-visible,button:focus-visible{outline:3px solid #ba8792;outline-offset:3px}@media(max-width:800px){.landscape-metrics{grid-template-columns:1fr 1fr;gap:24px 0}.landscape-metrics>div:nth-child(2){border-right:0}.landscape-readings{grid-template-columns:1fr;gap:0}.landscape-panel{padding:20px 14px}.map-legend small{width:100%;margin:0}.landscape-intro h3{font-size:21px}.landscape-intro{gap:16px}.intro-mark{padding-right:16px}.map-footer{flex-direction:column;gap:5px}.time-control{width:100%}.time-control input{flex:1}.map-dialog{padding:30px 24px}.map-dialog h3{font-size:25px}}
